@lru_cache(maxsize=1)
def rectangles():
    decoder=zlib.decompressobj();raw=decoder.decompress(bytes.fromhex(ENCODED),SIZE+1)
    if (len(raw)!=SIZE or not decoder.eof or decoder.unconsumed_tail or decoder.unused_data
            or hashlib.sha256(raw).hexdigest()!=SHA256):
        raise ValueError('CPU selector artwork is damaged')
    if struct.unpack_from('<I',raw)[0]!=10:raise ValueError('CPU selector plate count changed')
    result=[];offset=4
    for _ in range(10):
        count=struct.unpack_from('<I',raw,offset)[0];offset+=4
        if not 0<count<10240 or offset+count*11>len(raw):raise ValueError('CPU selector plate is truncated')
        rows=[]
        for _ in range(count):
            x0,y0,x1,y1,r,g,b=struct.unpack_from('<4H3B',raw,offset);offset+=11
            if not 0<=x0<x1<=512 or not 0<=y0<y1<=448:raise ValueError('CPU selector rectangle is out of bounds')
            rows.append((x0,y0,x1,y1,(r,g,b)))
        result.append(tuple(rows))
    if offset!=len(raw):raise ValueError('CPU selector artwork has trailing data')
    return tuple(result)
